
	WITH "DVO_BASE1" AS 
	( 
		SELECT DISTINCT
			  "DVO_SRC1"."COMPANY_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC1"."COMPANY_BK" AS "COMPANY_BK"
			, "SAT_SRC1_1_4"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
			, "SAT_SRC1_1_4"."ACCOUNT_NAME" AS "ACCOUNT_NAME"
		FROM {{ source('eli_dv_bv', 'hub_company') }} "DVO_SRC1"
		INNER JOIN {{ ref('sat_ssc_company_bvv_curr') }} "SAT_SRC1_1_4" ON  "DVO_SRC1"."COMPANY_HKEY" = "SAT_SRC1_1_4"."COMPANY_HKEY"
	)
	, "DVO_BASE3" AS 
	( 
		SELECT DISTINCT
			  "DVO_SRC3"."CANDIDATE_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC3"."CANDIDATE_BK" AS "CANDIDATE_BK"
			, "SAT_SRC3_1_6"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
			, "SAT_SRC3_1_6"."CAND_ID" AS "CAND_ID"
			, "SAT_SRC3_1_6"."MAIN_COUNTRY" AS "MAIN_COUNTRY"
			, "SAT_SRC3_1_6"."CANDIDATE_FULL_NAME" AS "CANDIDATE_FULL_NAME"
			, "SAT_SRC3_1_6"."CANDIDATE_EMAIL" AS "CANDIDATE_EMAIL"
			, "SAT_SRC3_1_6"."CANDIDATE_PHONE" AS "CANDIDATE_PHONE"
			, "SAT_SRC3_1_6"."TITLE" AS "TITLE"
			, "SAT_SRC3_1_6"."CANDIDATE_BH_ID" AS "CANDIDATE_BH_ID"
			, "SAT_SRC3_1_6"."CANDIDATE_LAST_NAME" AS "CANDIDATE_LAST_NAME"
			, "SAT_SRC3_1_6"."CANDIDATE_FIRST_NAME" AS "CANDIDATE_FIRST_NAME"
			, "SAT_SRC3_1_6"."MAIN_CITY" AS "MAIN_CITY"
			, "SAT_SRC3_1_6"."CANDIDATE_EMAIL_2" AS "CANDIDATE_EMAIL_2"
			, "SAT_SRC3_1_6"."MIDDLE_NAME" AS "MIDDLE_NAME"
			, "SAT_SRC3_1_6"."MAIN_STATE" AS "MAIN_STATE"
			, "SAT_SRC3_1_6"."MAILING_CITY" AS "MAILING_CITY"
			, "SAT_SRC3_1_6"."MAIN_STREET" AS "MAIN_STREET"
			, "SAT_SRC3_1_6"."MAILING_STATE" AS "MAILING_STATE"
			, "SAT_SRC3_1_6"."MAILING_STREET" AS "MAILING_STREET"
			, "SAT_SRC3_1_6"."MAILING_COUNTRY" AS "MAILING_COUNTRY"
			, "SAT_SRC3_1_6"."MAIN_STATE_CODE" AS "MAIN_STATE_CODE"
			, "SAT_SRC3_1_6"."SOURCE" AS "SOURCE"
			, "SAT_SRC3_1_6"."LINKEDIN_URL" AS "LINKEDIN_URL"
			, "SAT_SRC3_1_6"."MAIN_POSTAL_CODE" AS "MAIN_POSTAL_CODE"
			, "SAT_SRC3_1_6"."CANDIDATE_NICKNAME" AS "CANDIDATE_NICKNAME"
			, "SAT_SRC3_1_6"."LAST_ACTIVITY_DATE" AS "LAST_ACTIVITY_DATE"
			, "SAT_SRC3_1_6"."MAILING_STATE_CODE" AS "MAILING_STATE_CODE"
			, "SAT_SRC3_1_6"."FUNCTION" AS "FUNCTION"
			, "SAT_SRC3_1_6"."BIRTHDAY_MM_DD" AS "BIRTHDAY_MM_DD"
			, "SAT_SRC3_1_6"."MAILING_POSTAL_CODE" AS "MAILING_POSTAL_CODE"
			, "SAT_SRC3_1_6"."CLEARANCE_LEVEL" AS "CLEARANCE_LEVEL"
			, "SAT_SRC3_1_6"."HAS_OPTED_OUT_OF_EMAIL" AS "HAS_OPTED_OUT_OF_EMAIL"
			, "SAT_SRC3_1_6"."CANDIDATE_CONTRACTOR_TYPE" AS "CANDIDATE_CONTRACTOR_TYPE"
			, "SAT_SRC3_1_6"."DESIRED_HOURLY_RATE" AS "DESIRED_HOURLY_RATE"
			, "SAT_SRC3_1_6"."DESIRED_SALARY_RATE" AS "DESIRED_SALARY_RATE"
			, "SAT_SRC3_1_6"."ADP_FILE_NUMBER" AS "ADP_FILE_NUMBER"
			, "SAT_SRC3_1_6"."CANDIDATE_ELI_LEGACY_SYSTEM_ID" AS "CANDIDATE_ELI_LEGACY_SYSTEM_ID"
			, "SAT_SRC3_1_6"."CANDIDATE_STATUS" AS "CANDIDATE_STATUS"
			, "SAT_SRC3_1_6"."PRIMARY_BACKGROUND" AS "PRIMARY_BACKGROUND"
			, "SAT_SRC3_1_6"."AVAILABLE_FOR_REASSIGNMENT" AS "AVAILABLE_FOR_REASSIGNMENT"
			, "SAT_SRC3_1_6"."CANDIDATE_VIA_SF_LEGACY_ID" AS "CANDIDATE_VIA_SF_LEGACY_ID"
		FROM {{ source('eli_dv_bv', 'hub_candidate') }} "DVO_SRC3"
		INNER JOIN {{ ref('sat_ssc_candidate_bvv_curr') }} "SAT_SRC3_1_6" ON  "DVO_SRC3"."CANDIDATE_HKEY" = "SAT_SRC3_1_6"."CANDIDATE_HKEY"
	)
	, "DVO_BASE5" AS 
	( 
		SELECT DISTINCT
			  "DVO_SRC5"."USER_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC5"."USER_BK" AS "USER_BK"
			, "SAT_SRC5_1_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
			, "SAT_SRC5_1_1"."NAME" AS "NAME"
		FROM {{ source('eli_dv_bv', 'hub_user') }}"DVO_SRC5"
		INNER JOIN {{ ref('sat_ssc_user_bvv_curr') }} "SAT_SRC5_1_1" ON  "DVO_SRC5"."USER_HKEY" = "SAT_SRC5_1_1"."USER_HKEY"
	)
	, "DVO_BASE2" AS 
	( 
		SELECT DISTINCT
			  "DVO_SRC2"."CANDIDATE_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC2"."LNK_CANDIDATE_COMPANY_HKEY" AS "BASE_OBJECT_L_H_KEY"
			, "DVO_SRC2"."COMPANY_HKEY" AS "BASE_OBJECT_F_H_KEY"
            , ROW_NUMBER() OVER (
				PARTITION BY "DVO_SRC2"."CANDIDATE_HKEY" -- Partition by candidate to get the latest company
				ORDER BY "SAT_SRC2_1_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
			) AS "RN"
			, "SAT_SRC2_1_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
		FROM {{ source('eli_dv_bv', 'lnk_candidate_company') }} "DVO_SRC2"
		INNER JOIN {{ ref('lks_ssc_candidate_company_bvv_curr') }} "SAT_SRC2_1_1" ON  "DVO_SRC2"."LNK_CANDIDATE_COMPANY_HKEY" = "SAT_SRC2_1_1"."LNK_CANDIDATE_COMPANY_HKEY"
	)
	, "DVO_BASE4" AS 
	( 
		SELECT DISTINCT
			  "DVO_SRC4"."CANDIDATE_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC4"."LNK_CANDIDATE_USER_HKEY" AS "BASE_OBJECT_L_H_KEY"
			, "DVO_SRC4"."USER_HKEY" AS "BASE_OBJECT_F_H_KEY"
            , ROW_NUMBER() OVER (
				PARTITION BY "DVO_SRC4"."CANDIDATE_HKEY" -- Partition by candidate to get the latest user
				ORDER BY "SAT_SRC4_1_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
			) AS "RN"
			, "SAT_SRC4_1_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
		FROM {{ source('eli_dv_bv', 'lnk_candidate_user') }} "DVO_SRC4"
		INNER JOIN {{ ref('lks_ssc_candidate_user_bvv_curr') }} "SAT_SRC4_1_1" ON  "DVO_SRC4"."LNK_CANDIDATE_USER_HKEY" = "SAT_SRC4_1_1"."LNK_CANDIDATE_USER_HKEY"
	)
	SELECT 
		UPPER(SHA2(
			UPPER(REPLACE(COALESCE(TRIM(DVO_BASE3.CANDIDATE_BK),'~'), '\#', '\\\#')) || '\#' ||
			UPPER(REPLACE(COALESCE(TRIM(TO_CHAR(DVO_BASE3.SNAPSHOT__TIMESTAMP, 'DD/MM/YYYY HH24:MI:SS')),'~'), '\#', '\\\#')) || '\#'
		)) AS DIM_CANDIDATE_HKEY
		, "DVO_BASE3"."BASE_OBJECT_H_KEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_BASE3"."CANDIDATE_BK" AS "CANDIDATE_BK"
		, "DVO_BASE3"."SNAPSHOT__TIMESTAMP" AS "SNAPSHOT__TIMESTAMP"
		, "DVO_BASE3"."MAIN_COUNTRY" AS "MAIN_COUNTRY"
		, "DVO_BASE3"."CANDIDATE_FULL_NAME" AS "CANDIDATE_FULL_NAME"
		, "DVO_BASE3"."CANDIDATE_EMAIL" AS "CANDIDATE_EMAIL"
		, "DVO_BASE3"."CANDIDATE_PHONE" AS "CANDIDATE_PHONE"
		, "DVO_BASE3"."TITLE" AS "TITLE"
		, "DVO_BASE3"."CANDIDATE_BH_ID" AS "CANDIDATE_BH_ID"
		, "DVO_BASE3"."CANDIDATE_LAST_NAME" AS "CANDIDATE_LAST_NAME"
		, "DVO_BASE3"."CANDIDATE_FIRST_NAME" AS "CANDIDATE_FIRST_NAME"
		, "DVO_BASE3"."MAIN_CITY" AS "MAIN_CITY"
		, "DVO_BASE3"."CANDIDATE_EMAIL_2" AS "CANDIDATE_EMAIL_2"
		, "DVO_BASE3"."MIDDLE_NAME" AS "MIDDLE_NAME"
		, "DVO_BASE3"."MAIN_STATE" AS "MAIN_STATE"
		, "DVO_BASE3"."MAILING_CITY" AS "MAILING_CITY"
		, "DVO_BASE3"."MAIN_STREET" AS "MAIN_STREET"
		, "DVO_BASE3"."MAILING_STATE" AS "MAILING_STATE"
		, "DVO_BASE3"."MAILING_STREET" AS "MAILING_STREET"
		, "DVO_BASE3"."MAILING_COUNTRY" AS "MAILING_COUNTRY"
		, "DVO_BASE3"."MAIN_STATE_CODE" AS "MAIN_STATE_CODE"
		, "DVO_BASE3"."SOURCE" AS "SOURCE"
		, "DVO_BASE3"."LINKEDIN_URL" AS "LINKEDIN_URL"
		, "DVO_BASE3"."MAIN_POSTAL_CODE" AS "MAIN_POSTAL_CODE"
		, "DVO_BASE3"."CANDIDATE_NICKNAME" AS "CANDIDATE_NICKNAME"
		, "DVO_BASE3"."LAST_ACTIVITY_DATE" AS "LAST_ACTIVITY_DATE"
		, "DVO_BASE3"."MAILING_STATE_CODE" AS "MAILING_STATE_CODE"
		, "DVO_BASE3"."FUNCTION" AS "FUNCTION"
		, "DVO_BASE3"."BIRTHDAY_MM_DD" AS "BIRTHDAY_MM_DD"
		, "DVO_BASE3"."MAILING_POSTAL_CODE" AS "MAILING_POSTAL_CODE"
		, "DVO_BASE3"."CLEARANCE_LEVEL" AS "CLEARANCE_LEVEL"
		, "DVO_BASE3"."HAS_OPTED_OUT_OF_EMAIL" AS "HAS_OPTED_OUT_OF_EMAIL"
		, "DVO_BASE3"."CANDIDATE_CONTRACTOR_TYPE" AS "CANDIDATE_CONTRACTOR_TYPE"
		, "DVO_BASE3"."DESIRED_HOURLY_RATE" AS "DESIRED_HOURLY_RATE"
		, "DVO_BASE3"."DESIRED_SALARY_RATE" AS "DESIRED_SALARY_RATE"
		, "DVO_BASE3"."ADP_FILE_NUMBER" AS "ADP_FILE_NUMBER"
		, "DVO_BASE3"."CANDIDATE_ELI_LEGACY_SYSTEM_ID" AS "CANDIDATE_ELI_LEGACY_SYSTEM_ID"
		, "DVO_BASE3"."CANDIDATE_STATUS" AS "CANDIDATE_STATUS"
		, "DVO_BASE3"."PRIMARY_BACKGROUND" AS "PRIMARY_BACKGROUND"
		, "DVO_BASE3"."AVAILABLE_FOR_REASSIGNMENT" AS "AVAILABLE_FOR_REASSIGNMENT"
		, "DVO_BASE3"."CANDIDATE_VIA_SF_LEGACY_ID" AS "CANDIDATE_VIA_SF_LEGACY_ID"
		, "DVO_BASE1"."ACCOUNT_NAME" AS "SUPPLIER"
		, "DVO_BASE5"."NAME" AS "OWNER_NAME"
	FROM "DVO_BASE3" "DVO_BASE3" -- MAIN_HUB: HUB_CANDIDATE
    --Join HUB_CANDIDATE to link table on Primary key HKEY to get the company
    INNER JOIN "DVO_BASE2" "DVO_BASE2" ON  "DVO_BASE3"."BASE_OBJECT_H_KEY" = "DVO_BASE2"."BASE_OBJECT_H_KEY" 
        AND "DVO_BASE2"."RN" = 1 -- Get the latest company for the candidate
    --Join HUB_COMPANY to link table on Foreign key HKEY
    INNER JOIN "DVO_BASE1" "DVO_BASE1" ON  "DVO_BASE2"."BASE_OBJECT_F_H_KEY" = "DVO_BASE1"."BASE_OBJECT_H_KEY"
    --Join HUB_CANDIDATE to link table on Primary key HKEY to get the user
    INNER JOIN "DVO_BASE4" "DVO_BASE4" ON  "DVO_BASE3"."BASE_OBJECT_H_KEY" = "DVO_BASE4"."BASE_OBJECT_H_KEY" 
        AND "DVO_BASE4"."RN" = 1 -- Get the latest user for the candidate
    --Join HUB_USER to link table on Foreign key HKEY
    INNER JOIN "DVO_BASE5" "DVO_BASE5" ON  "DVO_BASE4"."BASE_OBJECT_F_H_KEY" = "DVO_BASE5"."BASE_OBJECT_H_KEY"
	